Implement caching improvements.

Read changes from: /tmp/dashboard-improvement/categorized-changes.json
Filter for category == 'caching'

For each caching change:

1. **Add localStorage cache layer** to monitor.js:
```javascript
const CacheManager = {
    prefix: 'dashboard_cache_',
    defaultTTL: 60000, // 1 minute

    get(key) {
        const item = localStorage.getItem(this.prefix + key);
        if (!item) return null;
        const { data, expiry } = JSON.parse(item);
        if (Date.now() > expiry) {
            localStorage.removeItem(this.prefix + key);
            return null;
        }
        return data;
    },

    set(key, data, ttl = this.defaultTTL) {
        localStorage.setItem(this.prefix + key, JSON.stringify({
            data,
            expiry: Date.now() + ttl
        }));
    },

    clear() {
        Object.keys(localStorage)
            .filter(k => k.startsWith(this.prefix))
            .forEach(k => localStorage.removeItem(k));
    }
};
```

2. **Integrate with fetchShape**:
```javascript
async function fetchShape(shapeName, params = {}) {
    const cacheKey = `${shapeName}:${JSON.stringify(params)}`;

    // Check localStorage cache first
    const cached = CacheManager.get(cacheKey);
    if (cached) {
        return { ...cached, cached: true, cacheSource: 'localStorage' };
    }

    // Fetch from API...
    const result = await fetchFromAPI(...);

    // Cache successful responses
    if (result.success) {
        CacheManager.set(cacheKey, result, getTTLForShape(shapeName));
    }

    return result;
}
```

